tool_args.command:
python3 << 'EOF'
import yaml
import json

with open("/home/ubuntu/.agent-ml-research-idea_gen_0514_1/projects/struct_self_consist_ie/registry.yaml") as f:
    data = yaml.safe_load(f)

if isinstance(data, dict) and "experiments" in data:
    experiments = data["experiments"]

    robustness_entries = {}

    for entry_id, entry in experiments.items():
        if not isinstance(entry, dict):
            continue

        # Check hypothesis
        hypothesis = ""
        if isinstance(entry.get("spec"), dict):
            hypothesis = entry["spec"].get("hypothesis", "")
        elif "hypothesis" in entry:
            hypothesis = entry.get("hypothesis", "")

        conclusion_note = entry.get("conclusion_note", "")

        if "robust" in str(hypothesis).lower() or "robust" in str(conclusion_note).lower():
            robustness_entries[entry_id] = {
                "status": entry.get("status", "N/A"),
                "hypothesis": hypothesis,
                "conclusion": entry.get("conclusion", "N/A"),
                "conclusion_note": conclusion_note,
                "metrics": entry.get("metrics", {}),
                "log_path": entry.get("log_path", "N/A"),
            }

    # Print in detail
    for entry_id in sorted(robustness_entries.keys()):
        entry = robustness_entries[entry_id]
        print(f"\n{'='*100}")
        print(f"EXPERIMENT ID: {entry_id}")
        print(f"STATUS: {entry['status']}")
        print(f"HYPOTHESIS: {entry['hypothesis']}")
        print(f"CONCLUSION: {entry['conclusion']}")
        if entry['conclusion_note']:
            print(f"CONCLUSION NOTE: {entry['conclusion_note']}")
        print(f"LOG PATH: {entry['log_path']}")

        metrics = entry['metrics']
        if metrics:
            print(f"\nMETRICS ({len(metrics)} items):")
            for k, v in sorted(metrics.items())[:15]:
                if isinstance(v, dict):
                    print(f"  {k}: {json.dumps(v, indent=4)[:200]}...")
                else:
                    print(f"  {k}: {v}")
EOF
